<script>
if(!window.__vfnAtcDuplicate){
document.getElementById('fullscreenButton').addEventListener('click',function(){document.documentElement.requestFullscreen?.().catch(()=>{});});
const atcOptionsButton=document.getElementById('atcOptionsButton'),atcOptionsMenu=document.getElementById('atcOptionsMenu');
atcOptionsButton.addEventListener('click',event=>{event.stopPropagation();atcOptionsMenu.hidden=!atcOptionsMenu.hidden;});
atcOptionsMenu.addEventListener('click',event=>event.stopPropagation());
document.addEventListener('click',()=>{atcOptionsMenu.hidden=true;});
document.getElementById('closeAtcButton').addEventListener('click',async function(){this.disabled=true;try{await fetch('execute/atc_session_stop.php',{method:'POST',keepalive:true});}catch(error){}try{window.close();}catch(error){}setTimeout(()=>{if(!window.closed)window.location.replace('index.php');},120);});
const atcInstanceId=window.__vfnAtcInstanceId;const detachedAtcWindows=new Set();let atcChannel=null;
function writeAtcHeartbeat(){localStorage.setItem('vfn-atc-client-active',JSON.stringify({instance:atcInstanceId,timestamp:Date.now()}));}
function focusActiveAtcWindow(){for(const popup of detachedAtcWindows){if(popup&&!popup.closed){popup.focus();return;}}window.focus();}
writeAtcHeartbeat();const atcHeartbeatTimer=setInterval(writeAtcHeartbeat,1000);
if(typeof BroadcastChannel!=='undefined'){atcChannel=new BroadcastChannel('vfn-atc-client');atcChannel.addEventListener('message',event=>{if(event.data?.type==='focus')focusActiveAtcWindow();});}
window.addEventListener('storage',event=>{if(event.key==='vfn-atc-focus-request')focusActiveAtcWindow();});
window.addEventListener('beforeunload',()=>{clearInterval(atcHeartbeatTimer);atcChannel?.close();for(const popup of detachedAtcWindows){try{popup.close();}catch(error){}}try{const active=JSON.parse(localStorage.getItem('vfn-atc-client-active')||'null');if(active?.instance===atcInstanceId)localStorage.removeItem('vfn-atc-client-active');}catch(error){}});
function initializeAtcWindow(panel){
    const workspace=panel.closest('.workspace');const dockParent=panel.parentElement;const bar=panel.querySelector('.window-bar');const detachButton=panel.querySelector('[data-action="detach"]');const dockButton=panel.querySelector('[data-action="dock"]');const key=panel.dataset.windowKey||panel.id;let popup=null,drag=null,closeWatch=null;
    const actions=bar.querySelector('.window-actions');const collapseButton=document.createElement('button');collapseButton.type='button';collapseButton.className='window-action';collapseButton.dataset.action='collapse';actions.insertBefore(collapseButton,actions.firstChild);function setCollapsed(collapsed){panel.classList.toggle('is-collapsed',collapsed);collapseButton.textContent=collapsed?'□':'–';collapseButton.title=collapsed?'Fenster ausklappen':'Fenster einklappen';localStorage.setItem('vfn-atc-window-collapsed-'+key,collapsed?'1':'0');if(popup&&!popup.closed)popup.resizeTo(Math.max(360,popup.outerWidth),collapsed?125:Math.max(420,popup.outerHeight));}setCollapsed(localStorage.getItem('vfn-atc-window-collapsed-'+key)==='1');collapseButton.addEventListener('click',event=>{event.stopPropagation();setCollapsed(!panel.classList.contains('is-collapsed'));});
    function savePosition(){if(panel.classList.contains('is-detached'))return;localStorage.setItem('vfn-atc-window-'+key,JSON.stringify({left:panel.style.left,top:panel.style.top}));}
    function restorePosition(){try{const saved=JSON.parse(localStorage.getItem('vfn-atc-window-'+key)||'null');if(saved?.left&&saved?.top){panel.style.position='absolute';panel.style.left=saved.left;panel.style.top=saved.top;panel.style.right='auto';panel.style.bottom='auto';return true;}}catch(error){}return false;}
    function dock(){if(!popup)return;detachedAtcWindows.delete(popup);dockParent.appendChild(panel);panel.classList.remove('is-detached');panel.style.right='';panel.style.bottom='';if(!restorePosition()){panel.style.position='';panel.style.left='';panel.style.top='';}try{popup.close();}catch(error){}popup=null;if(closeWatch){clearInterval(closeWatch);closeWatch=null;}}
    function detach(){if(popup&&!popup.closed){popup.focus();return;}popup=window.open('','vfn_atc_'+key.replace(/[^a-z0-9]/gi,'_'),'popup=yes,width=1100,height=760,resizable=yes,scrollbars=yes');if(!popup)return;detachedAtcWindows.add(popup);popup.document.open();popup.document.write('<!doctype html><html lang="<?php echo addslashes($currentLanguage); ?>"><head><meta charset="utf-8"><title>'+panel.querySelector('.window-title').textContent.replace(/[<>&]/g,'')+' – VFN</title>'+Array.from(document.querySelectorAll('style')).map(style=>'<style>'+style.textContent+'@keyframes radar-ident-flash{0%,100%{filter:none;opacity:1}50%{filter:brightness(3);opacity:.25}}.radar-target-diamond.ident-active,.radar-target-label.ident-active{animation:radar-ident-flash .42s linear infinite;color:#fff;background-color:#dfff76;box-shadow:0 0 18px #fff}</style>').join('')+'</head><body></body></html>');popup.document.close();popup.document.body.appendChild(panel);panel.classList.add('is-detached');panel.style.position='relative';panel.style.left='';panel.style.top='';panel.style.right='auto';panel.style.bottom='auto';popup.document.documentElement.style.overflow='auto';popup.document.body.style.overflow='auto';closeWatch=setInterval(()=>{if(popup&&popup.closed)dock();},400);}
    panel.__fitDetachedHeight=()=>{if(!popup||popup.closed||!panel.classList.contains('is-detached'))return;const chrome=Math.max(70,popup.outerHeight-popup.innerHeight),content=Math.ceil(panel.getBoundingClientRect().height)+chrome+12,target=Math.max(180,Math.min((popup.screen?.availHeight||900)-40,content));try{popup.resizeTo(popup.outerWidth,target);}catch(error){}};
    detachButton.addEventListener('click',event=>{event.stopPropagation();detach();setTimeout(()=>panel.__fitDetachedHeight?.(),80);});dockButton.addEventListener('click',event=>{event.stopPropagation();dock();});
    bar.addEventListener('pointerdown',event=>{if(panel.classList.contains('is-detached')||event.target.closest('button'))return;const panelRect=panel.getBoundingClientRect();const workspaceRect=workspace.getBoundingClientRect();panel.style.position='absolute';panel.style.left=(panelRect.left-workspaceRect.left+workspace.scrollLeft)+'px';panel.style.top=(panelRect.top-workspaceRect.top+workspace.scrollTop)+'px';panel.style.right='auto';panel.style.bottom='auto';drag={x:event.clientX,y:event.clientY,left:parseFloat(panel.style.left),top:parseFloat(panel.style.top),pointer:event.pointerId};bar.setPointerCapture(event.pointerId);});
    bar.addEventListener('pointermove',event=>{if(!drag||event.pointerId!==drag.pointer)return;const maxLeft=Math.max(0,workspace.scrollWidth-panel.offsetWidth);const maxTop=Math.max(0,workspace.scrollHeight-panel.offsetHeight);panel.style.left=Math.max(0,Math.min(maxLeft,drag.left+event.clientX-drag.x))+'px';panel.style.top=Math.max(0,Math.min(maxTop,drag.top+event.clientY-drag.y))+'px';});
    function finishDrag(event){if(!drag||event.pointerId!==drag.pointer)return;drag=null;savePosition();}
    bar.addEventListener('pointerup',finishDrag);bar.addEventListener('pointercancel',finishDrag);restorePosition();
    panel.__dockAtcWindow=dock;
}
document.querySelectorAll('.detachable-window').forEach(initializeAtcWindow);
