    if(select)return select;
    const row=document.createElement('div');row.className='atis-selector-row';
    select=document.createElement('select');select.id='atcAtisAirport';select.setAttribute('aria-label','ATIS airport');
    const popupButton=document.createElement('button');popupButton.type='button';popupButton.className='window-action';popupButton.id='atcAtisNewWindow';popupButton.textContent='＋';popupButton.title='ATIS in neuem Fenster öffnen';
