function observeAtisRunways(airports){
    (Array.isArray(airports)?airports:[]).forEach(item=>{
        const icao=String(item.icao||''),runway=String(item.active_runway||''),previous=atisKnownRunways.get(icao);
        if(previous!==undefined&&previous!==''&&runway!==''&&previous!==runway){
            appendAtcChatMessage({time:new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}),sender:'SYSTEM',text:'<?php echo addslashes(t('atc_atis_runway_changed')); ?>'.replace('%airport%',icao).replace('%old%',previous).replace('%new%',runway)});
        }
