let radarSectorLayoutTimer=null,radarSectorLayoutRequest=0,radarSectorLayoutKey='';
function scheduleSectorAirportLayouts(){
    const position=String(currentAtcSession?.position_code||'').toUpperCase();
    if(!['APP','DEP','CTR'].includes(position))return;
    clearTimeout(radarSectorLayoutTimer);
    radarSectorLayoutTimer=setTimeout(()=>loadSectorAirportGroundLayouts(currentAtcSession,false),220);
}
async function loadSectorAirportGroundLayouts(session,force=false){
    if(!radarMap)return;
    if(radarMap.getZoom()<12){clearAirportGroundLayout();radarSectorLayoutKey='';return;}
    const bounds=radarMap.getBounds().pad(.08),params=new URLSearchParams({
        south:String(bounds.getSouth()),north:String(bounds.getNorth()),
        west:String(bounds.getWest()),east:String(bounds.getEast())
    });
