    try{
        const response=await fetch('execute/atc_layout_airports.php?'+params.toString(),{cache:'no-store'}),payload=await response.json();
        if(!response.ok||!payload.success)throw new Error(payload.message||'airport_layout_scope_failed');
        const airports=Array.isArray(payload.airports)?payload.airports:[],key=airports.map(item=>String(item.icao||'')).sort().join(',');
        if(!force&&key===radarSectorLayoutKey)return;
        const base=L.layerGroup(),labels=L.layerGroup(),stands=L.layerGroup(),loaded=[];
        for(const airport of airports.slice(0,120)){
            if(request!==radarSectorLayoutRequest)return;
            const icao=String(airport.icao||'').toUpperCase();if(!icao)continue;
            await loadAirportGroundLayout({...session,station_code:icao,position_code:'APP'});
            if(radarAirportLayoutLayer){radarAirportLayoutLayer.getLayers().forEach(layer=>base.addLayer(layer));}
            if(radarAirportLabelLayer){radarAirportLabelLayer.getLayers().forEach(layer=>labels.addLayer(layer));}
            if(radarAirportStandLayer){radarAirportStandLayer.getLayers().forEach(layer=>stands.addLayer(layer));}
            if(radarAirportLayoutLayer)loaded.push(icao);
        }
        if(request!==radarSectorLayoutRequest)return;
        clearAirportGroundLayout();radarAirportLayoutLayer=base;radarAirportLabelLayer=labels;radarAirportStandLayer=stands;
        radarAirportLayoutIcao=loaded.join(',');radarSectorLayoutKey=key;
        if(loaded.length){radarAirportLayoutBadge=document.createElement('div');radarAirportLayoutBadge.className='airport-layout-badge';radarAirportLayoutBadge.textContent=loaded.length+' AIRPORT LAYOUTS';document.getElementById('atcRadarMap').appendChild(radarAirportLayoutBadge);}
        refreshAirportLayoutVisibility();
    }catch(error){if(request===radarSectorLayoutRequest)console.warn('Sector airport layouts unavailable',error);}
}
function atcNavigationIcon(point){const identifier=escapeText(point.identifier||'');return L.divIcon({className:'',html:'<div class="atc-nav-point '+(point.kind==='navaid'?'navaid':'waypoint')+'">'+identifier+'</div>',iconSize:[100,14],iconAnchor:[4,7]});}
async function loadRadarNavigation(){
    if(!radarNavigationLayer)return;if(!radarNavigationLayer.__vfnOptimizedEvents){radarMap.off('move',radarNavigationLayer.schedule,radarNavigationLayer);radarMap.off('zoom',radarNavigationLayer.schedule,radarNavigationLayer);radarMap.on('moveend zoomend',radarNavigationLayer.schedule,radarNavigationLayer);radarNavigationLayer.__vfnOptimizedEvents=true;}radarNavigationPoints=[];radarNavigationLayer.clearLayers();const status=document.getElementById('radarNavigationStatus'),cacheKey='vfn-atc-nav-'+String(currentAtcSession?.callsign||'default');if(status)status.textContent=radarNavigationVisible?'NAV: lädt …':'NAV: ausgeblendet';
    try{const cached=JSON.parse(sessionStorage.getItem(cacheKey)||'null');if(Array.isArray(cached?.points)&&Date.now()-Number(cached.timestamp||0)<21600000){radarNavigationPoints=cached.points;radarNavigationLayer.setPoints(radarNavigationPoints);if(status)status.textContent=radarNavigationVisible?'NAV: '+radarNavigationPoints.length+' Punkte':'NAV: ausgeblendet';return;}}catch(error){}
    const rendered=new Set(),points=[];
    for(let page=1;page<=40;page++){
        try{
            const response=await fetch('execute/atc_navigation.php?page='+page+'&_='+Date.now(),{cache:'no-store',credentials:'same-origin'}),data=await response.json();
            if(!response.ok||!data.success)throw new Error(data.message||'navigation_unavailable');
            (data.points||[]).forEach(point=>{const latitude=Number(point.latitude),longitude=Number(point.longitude);if(!Number.isFinite(latitude)||!Number.isFinite(longitude))return;const key=String(point.kind||'')+':'+String(point.identifier||'')+':'+latitude.toFixed(5)+':'+longitude.toFixed(5);if(rendered.has(key))return;rendered.add(key);points.push({...point,latitude,longitude});});
            if(status&&radarNavigationVisible)status.textContent='NAV: '+rendered.size+' Punkte'+(data.has_more?' · lädt …':'');
            if(!data.has_more)break;
            await new Promise(resolve=>setTimeout(resolve,5));
        }catch(error){console.warn('ATC navigation unavailable',error);if(status)status.textContent='NAV: Fehler · '+String(error.message||error);break;}
    }
