}
async function loadRadarMaterial(session){
    initializeRadarMap();
    const savedMapView=readRadarMapView(session);
    radarMapMaterialLoading=true;
    radarMap.__vfnCentered=false;
    radarMap.setMinZoom(2);
    radarMap.setMaxZoom(23);
    radarMap.setMaxBounds([[-85,-180],[85,180]]);
    if(radarFirLayer){radarFirLayer.remove();radarFirLayer=null;}
    const position=String(session.position_code||'').toUpperCase();
    try{
        let response=null;
        let filter=null;
        if(position==='CTR'){
            const station=String(session.station_code||'').toUpperCase();
            const detailedResponse=await fetch(
                'execute/sector_boundaries.php?station='+encodeURIComponent(station)
            );
            if(detailedResponse.ok){
                const detailed=await detailedResponse.json();
                radarFirLayer=L.geoJSON(detailed.geojson||{type:'FeatureCollection',features:[]},{
                    style:{color:'#78ff91',weight:2,fillColor:'#123b1d',fillOpacity:.16}
                }).addTo(radarMap);
            }else{
                response=await fetch('execute/fir_boundaries.php');
                const fallback=String(session.radar_boundary_code||'').toUpperCase();
                if(!response.ok)throw new Error('Boundary data unavailable');
                const geo=await response.json();
                const geoHasExactSector=(geo.features||[]).some(feature=>
                    String(feature.properties?.id||'').toUpperCase()===station
                );
                filter=feature=>{
                    const id=String(feature.properties?.id||'').toUpperCase();
                    return id===station||(!geoHasExactSector&&id===fallback);
                };
                radarFirLayer=L.geoJSON(geo,{
                    filter:filter,
                    style:{
                        color:geoHasExactSector?'#78ff91':'#a89070',weight:2,
                        fillColor:geoHasExactSector?'#123b1d':'#302a20',
                        fillOpacity:geoHasExactSector ? .16 : .05,
                        dashArray:geoHasExactSector?null:'3 8'
                    }
                }).addTo(radarMap);
                response=null;
            }
        }else if(position==='APP'||position==='DEP'){
            response=await fetch('execute/tracon_boundaries.php');
            const station=String(session.station_code||'').toUpperCase();
            filter=feature=>{
                const properties=feature.properties||{};
                const prefixes=Array.isArray(properties.prefix)?properties.prefix:[properties.prefix];
                const suffix=String(properties.suffix||'APP').toUpperCase();
                return prefixes.some(prefix=>String(prefix||'').toUpperCase()===station)&&suffix===position;
            };
        }
        if(response){
            if(!response.ok)throw new Error('Boundary data unavailable');
            const geo=await response.json();
            radarFirLayer=L.geoJSON(geo,{filter:filter,style:{
                color:'#78ff91',weight:2,fillColor:'#123b1d',fillOpacity:.16
            }}).addTo(radarMap);
        }
        if(radarFirLayer&&radarFirLayer.getLayers().length){
            const bounds=radarFirLayer.getBounds().pad(.18);
            radarMap.fitBounds(bounds,{padding:[30,30]});
            const fittedZoom=radarMap.getZoom();
            radarMap.setMinZoom(Math.max(2,fittedZoom-1));
            radarMap.setMaxZoom(23);
            radarMap.setMaxBounds(bounds);
            radarMap.__vfnCentered=true;
        }
    }catch(error){console.error(error);}
    await loadAirportGroundLayout(session);
    if(['APP','DEP'].includes(position)&&radarMap.getZoom()>=12){
        await loadSectorAirportGroundLayouts(session,true);
    }
    if(savedMapView){
        const zoom=Math.max(radarMap.getMinZoom(),Math.min(radarMap.getMaxZoom(),savedMapView.zoom));
        radarMap.setView(savedMapView.center,zoom,{animate:false});
    }
    radarMapMaterialLoading=false;
    void loadRadarNavigation();
    setTimeout(()=>radarMap.invalidateSize(),80);
}
