        L.polyline(points.map(point=>[Number(point.latitude),Number(point.longitude)]),{pane:'flightRoutePane',color:'#ffb347',weight:2.5,opacity:1,dashArray:'9 7',interactive:false}).addTo(radarFlightRouteLayer);
        points.forEach(point=>{const identifier=escapeText((point.procedure?point.procedure+' · ':'')+(point.identifier||'')),icon=L.divIcon({className:'',html:'<div class="atc-route-point">'+identifier+'</div>',iconSize:[120,14],iconAnchor:[3,7]});L.marker([Number(point.latitude),Number(point.longitude)],{pane:'flightRoutePane',icon:icon,interactive:false,keyboard:false}).addTo(radarFlightRouteLayer);});
    }catch(error){console.warn('Flight route unavailable',error);clearRadarFlightRoute();alert('<?php echo addslashes(t('atc_route_unavailable')); ?>');}
}
