function updateRadarTrail(target,targetLatLng,pilot){const last=target.trailPositions[target.trailPositions.length-1],minimumDistance=Number(pilot.on_ground)?8:35;if(!last||last.distanceTo(targetLatLng)>=minimumDistance){target.trailPositions.push(targetLatLng);if(target.trailPositions.length>240)target.trailPositions.shift();}renderRadarTrail(target);}
function updateRadarTarget(pilot,showDetails){const callsign=String(pilot.callsign||'').trim();if(!callsign)return;const targetLatLng=L.latLng(Number(pilot.latitude),Number(pilot.longitude));let target=radarTargets.get(callsign);if(!target){const trailLine=L.polyline([],{color:'#8dff9b',weight:2,opacity:.72,dashArray:'2 8',lineCap:'round',interactive:false}),targetMarker=L.marker(targetLatLng,{icon:radarDiamondIcon(),keyboard:false,interactive:true});target={callsign,targetMarker,trailLine,trailPositions:[],labelMarker:null,leaderLine:null,pilot};trailLine.addTo(radarTrafficLayer);targetMarker.addTo(radarTrafficLayer);radarTargets.set(callsign,target);attachRadarTargetContext(target,targetMarker);}target.pilot=pilot;updateRadarTrail(target,targetLatLng,pilot);target.targetMarker.setLatLng(targetLatLng);if(!showDetails){removeRadarTargetLabel(target);refreshInitialContactVisuals();return;}if(!target.labelMarker)attachRadarTargetLabel(target,pilot,targetLatLng);target.labelMarker.setIcon(radarLabelIcon(pilot));target.labelMarker.setLatLng(radarLabelLatLng(targetLatLng,radarDisplayOffset(radarLabelOffsets.get(callsign))));updateRadarLeader(target);refreshInitialContactVisuals();const ident=Number(pilot.transponder_mode)>=4;target.targetMarker.getElement()?.querySelector('.radar-target-diamond')?.classList.toggle('ident-active',ident);target.labelMarker?.getElement()?.querySelector('.radar-target-label')?.classList.toggle('ident-active',ident);}
async function pollAtcTraffic(){try{const response=await fetch('execute/atc_traffic.php',{cache:'no-store'});const data=await response.json();if(!response.ok||!data.success)return;initializeRadarMap();loadRadarLabelOffsets();if(data.center&&currentAtcSession?.position_code!=='CTR')applyAirportRadarLimits(currentAtcSession,data.center);const traffic=Array.isArray(data.traffic)?data.traffic:[];const active=new Set(traffic.map(pilot=>String(pilot.callsign||'').trim()).filter(Boolean));Array.from(radarTargets.keys()).forEach(callsign=>{if(!active.has(callsign))removeRadarTarget(callsign);});const list=document.getElementById('radarTrafficList');list.innerHTML='';traffic.forEach(pilot=>{const transponderOn=Number(pilot.transponder_mode)>=2,latitude=Number(pilot.latitude),longitude=Number(pilot.longitude),assumed=Number(pilot.assumed_by_me)===1;updateRadarTarget(pilot,transponderOn);const row=document.createElement('button');row.type='button';row.className='traffic-row radar-traffic-jump';row.innerHTML='<strong>'+(assumed?'[ASSUMED] ':'')+escapeText(transponderOn?pilot.callsign:'◆')+'</strong> · '+escapeText(pilot.aircraft_icao||'')+' · '+Math.round(Number(pilot.altitude||0))+' ft<span class="traffic-route">'+escapeText(pilot.pilot_name||'–')+'</span><span class="traffic-route">'+escapeText(pilot.departure_airport||'ZZZZ')+' &gt; '+escapeText(pilot.arrival_airport||'ZZZZ')+'</span>';row.addEventListener('click',()=>{if(!Number.isFinite(latitude)||!Number.isFinite(longitude))return;const targetZoom=Math.min(radarMap.getMaxZoom(),Math.max(radarMap.getZoom(),13));radarMap.flyTo([latitude,longitude],targetZoom,{animate:true,duration:.65});});row.addEventListener('contextmenu',event=>{event.preventDefault();const target=radarTargets.get(String(pilot.callsign||'').trim());if(target)positionRadarContextMenu(event,target);});attachLongPressContext(row,()=>radarTargets.get(String(pilot.callsign||'').trim()));list.appendChild(row);});if(!traffic.length)list.innerHTML='<div class="radar-empty">–</div>';}catch(error){}}
