async function openAtcFlightplan(target){closeRadarContextMenu();const dialog=document.getElementById('atcFlightplanDialog'),form=document.getElementById('atcFlightplanForm'),status=document.getElementById('atcFlightplanStatus'),save=form.querySelector('[type="submit"]');dialog.hidden=false;form.dataset.callsign=target.callsign;document.getElementById('atcFlightplanTitle').textContent=target.callsign+' · Flugplan';status.textContent='Lade Flugplan …';try{const response=await fetch('execute/atc_flightplan_manage.php?callsign='+encodeURIComponent(target.callsign),{cache:'no-store'}),data=await response.json();if(!response.ok||!data.success)throw new Error(data.message||'flightplan_load_failed');for(const [name,value] of Object.entries(data.flightplan||{})){if(form.elements[name])form.elements[name].value=String(value??'');}const editable=Boolean(data.assumed_by_me);Array.from(form.elements).forEach(element=>{if(element.name)element.disabled=!editable;});save.disabled=!editable;status.textContent=editable?'':'<?php echo addslashes(t('atc_flightplan_read_only')); ?>';}catch(error){status.textContent=String(error.message||error);}}
