function appendAtcChatMessage(message){const id=Number(message.id||0);if(id>0&&atcChatRenderedIds.has(id))return;if(id>0)atcChatRenderedIds.add(id);const line=document.createElement('div');line.className='atc-chat-line';line.innerHTML='<span class="atc-chat-time">'+escapeText(message.time||'')+'</span><span class="atc-chat-sender">'+escapeText(message.sender||'–')+'</span><span>'+escapeText(message.text||'')+'</span>';atcChatLog.appendChild(line);while(atcChatLog.children.length>200)atcChatLog.firstElementChild?.remove();atcChatLog.scrollTop=atcChatLog.scrollHeight;}
async function pollAtcChat(reset=false){const frequency=normalizeAtcFrequency(atcChatFrequency.value);if(!frequency||atcChatRequestInFlight)return;if(reset||frequency!==atcChatFrequencyValue){atcChatFrequencyValue=frequency;atcChatSinceId=0;atcChatLog.innerHTML='';atcChatRenderedIds.clear();}atcChatRequestInFlight=true;try{const response=await fetch('execute/atc_chat.php?frequency='+encodeURIComponent(frequency)+'&since_id='+atcChatSinceId,{cache:'no-store'}),data=await response.json();if(!response.ok||!data.success)throw new Error(data.message||'chat_failed');(data.messages||[]).forEach(appendAtcChatMessage);atcChatSinceId=Math.max(atcChatSinceId,Number(data.last_id||0));}catch(error){}finally{atcChatRequestInFlight=false;}}
